import{_ as t,r as a,c as o,d as r,a as i,o as n}from"./app-VPPMr0U6.js";const p={},c=i('<p>你好呀，我是苍何！</p><p>欢迎来到面试系列！这篇文章将会手把手教你如何用redis分布式锁保障PmHub项目中的流程状态更新，以下描述你可以直接写进简历，也可以根据你的理解进行优化。注意这是重点必须掌握的知识点！</p><ul><li>使用 Redis 分布式锁，确保流程状态更新按顺序执行且不被其他操作干扰，保护流程状态的更新过程。</li></ul><h2 id="什么是锁-本地锁的问题" tabindex="-1"><a class="header-anchor" href="#什么是锁-本地锁的问题"><span>什么是锁？本地锁的问题</span></a></h2><p>程序系统中所说的锁和现实中的锁其实概念差不多，都是用来锁住资源，以防止别人乱访问。</p><p>在说分布式锁之前，我们先看看看本地所的问题，以此来引申出分布式锁。</p><p>假设流程服务部署了 4 份，他们分别位于不同的服务器下面，前端请求进来到 Nginx 和网关后会被转发到不同的实例，假设前端接收 10w 个请求，每个实例服务接收 2.5w 个请求。</p><p>在每一个服务实例下，假设缓存失效，对其访问数据库操作加锁，通过锁（synchronzied 或 lock）来锁住自己的线程资源，从而防止缓存击穿。</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/本地锁.webp" alt="本地锁" tabindex="0" loading="lazy"><figcaption>本地锁</figcaption></figure><p>synchronized锁是Java提供的一种内置锁，在单个JVM进程中提供线程之间的锁定机制，控制多线程并发。只适用于单机环境下的并发控制。</p><p>但是在分布式系统中，如果想要锁定多个节点服务，synchronized就不适用于了，会带来数据不一致的问题：比如服务 A 获取数据后，更新缓存 key = 100，服务 B 不受服务 A 的锁限制，并发去更新缓存 key = 99，最后的结果可能是 99 或 100，但这是一种未知的状态，与期望结果不一致。</p><p>本教程大纲：</p><p><img src="https://cdn.tobebetterjavaer.com/stutymore/20240807204459.png" alt="本教程大纲" loading="lazy">：</p><h2 id="什么是分布式锁" tabindex="-1"><a class="header-anchor" href="#什么是分布式锁"><span>什么是分布式锁</span></a></h2><p>基于上面本地锁的问题，我们需要一种支持分布式集群环境下的锁：查询 DB 时，只有一个线程能访问，其他线程都需要等待第一个线程释放锁资源后，才能继续执行。</p><p>想要在多个节点中提供锁定，在分布式系统并发控制共享资源，确保同一时刻只有一个访问可以调用，避免多个调用者竞争调用和数据不一致问题，保证数据的一致性，就可以利用分布式锁。</p><p>分布式锁就是控制分布式系统不同进程访问共享资源的一种锁的机制。不同进程之间调用需要保持互斥性，任意时刻，只有一个客户端能持有锁。</p><p>从单体锁到分布式锁，只不过是将锁的对象从一个进程的多个线程，转成多个进程。如图所示：</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/分布式锁.webp" alt="分布式锁" tabindex="0" loading="lazy"><figcaption>分布式锁</figcaption></figure><h2 id="分布式锁特性" tabindex="-1"><a class="header-anchor" href="#分布式锁特性"><span>分布式锁特性</span></a></h2>',20);function s(d,l){const e=a("PaidContentBanner");return n(),o("div",null,[c,r(e)])}const u=t(p,[["render",s],["__file","redis-lock-process-update.html.vue"]]),h=JSON.parse('{"path":"/pmhub/interview/redis-lock-process-update.html","title":"PmHub集成Redis分布式锁保障流程状态更新（👍必看）","lang":"zh-CN","frontmatter":{"title":"PmHub集成Redis分布式锁保障流程状态更新（👍必看）","shortTitle":"PmHub集成Redis分布式锁","date":"2024-08-07T06:38:56.000Z","categories":["PmHub","面试系列"],"requiresAuth":true,"description":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。","head":[["meta",{"name":"keywords","content":"PmHub,Spring  Cloud,微服务,AI,知识星球,沉默王二,二哥的Java进阶之路,二哥的编程星球,Java进阶之路,编程,Java,IT,计算机专业,付费专栏,实战项目,分布式"}],["meta",{"property":"og:url","content":"https://laigeoffer.cn/pmhub/interview/redis-lock-process-update.html"}],["meta",{"property":"og:site_name","content":"来个offer"}],["meta",{"property":"og:title","content":"PmHub集成Redis分布式锁保障流程状态更新（👍必看）"}],["meta",{"property":"og:description","content":"PmHub 拆分了用户、流程、项目管理、认证等 4 个微服务，整合了 Redis 缓存、RocketMQ 消息队列、Docker 容器、Jenkins 自动化部署、Spring Security 安全框架、Nacos 服务注册和发现、Spring Boot Actuator 服务监控、Skywalking 链路追踪、Sentinel 熔断降级、Seata 分布式事务、Vue 前端框架等互联网开发中需要用到的绝大多数主流技术栈。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://cdn.tobebetterjavaer.com/stutymore/本地锁.webp"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-08-09T02:48:07.000Z"}],["meta",{"property":"article:author","content":"苍何&沉默王二"}],["meta",{"property":"article:published_time","content":"2024-08-07T06:38:56.000Z"}],["meta",{"property":"article:modified_time","content":"2024-08-09T02:48:07.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"PmHub集成Redis分布式锁保障流程状态更新（👍必看）\\",\\"image\\":[\\"https://cdn.tobebetterjavaer.com/stutymore/本地锁.webp\\",\\"https://cdn.tobebetterjavaer.com/stutymore/20240807204459.png\\",\\"https://cdn.tobebetterjavaer.com/stutymore/分布式锁.webp\\"],\\"datePublished\\":\\"2024-08-07T06:38:56.000Z\\",\\"dateModified\\":\\"2024-08-09T02:48:07.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"苍何&沉默王二\\",\\"url\\":\\"https://github.com/laigeoffer\\"}]}"]]},"headers":[{"level":2,"title":"什么是锁？本地锁的问题","slug":"什么是锁-本地锁的问题","link":"#什么是锁-本地锁的问题","children":[]},{"level":2,"title":"什么是分布式锁","slug":"什么是分布式锁","link":"#什么是分布式锁","children":[]},{"level":2,"title":"分布式锁特性","slug":"分布式锁特性","link":"#分布式锁特性","children":[]}],"git":{"createdTime":1723047302000,"updatedTime":1723171687000,"contributors":[{"name":"canghe","email":"2689458656@qq.com","commits":2}]},"readingTime":{"minutes":3.26,"words":977},"filePathRelative":"pmhub/interview/redis-lock-process-update.md","localizedDate":"2024年8月7日"}');export{u as comp,h as data};
